#!/usr/bin/env bash
set -Eeuo pipefail

UPDATE_NAME="Update 003 - Profiles, Appearance, Themes and Favicon"
UPDATE_NUMBER="003"
DB_NAME="dnsapproval"
PORTAL_ROOT="/opt/portal"

log() {
    echo
    echo "======================================================================"
    echo "$1"
    echo "======================================================================"
}

ok() {
    echo "[ OK ] $1"
}

warn() {
    echo "[WARN] $1"
}

fail() {
    echo "[ERROR] $1" >&2
    exit 1
}

log "$UPDATE_NAME"

[[ $EUID -eq 0 ]] || fail "This update must be run as root"
[[ -d "$PORTAL_ROOT" ]] || fail "Portal directory not found: $PORTAL_ROOT"

for cmd in awk base64 curl find grep gzip install php pg_dump pg_restore \
    psql python3 sha256sum stat sudo systemctl tar; do
    command -v "$cmd" >/dev/null 2>&1 \
        || fail "Required command not found: $cmd"
done

CURRENT_LEVEL="$(cat /var/lib/portal/update-version 2>/dev/null || echo 0)"
[[ "$CURRENT_LEVEL" =~ ^[0-9]+$ ]] \
    || fail "Invalid installed update level: $CURRENT_LEVEL"

[[ "$CURRENT_LEVEL" -eq 2 ]] \
    || fail "Update 003 requires installed update level 2; found $CURRENT_LEVEL"

###############################################################################
# Database preflight
###############################################################################

log "VALIDATING PORTAL DATABASE"

sudo -u postgres psql -d "$DB_NAME" -Atqc "SELECT 1" >/dev/null \
    || fail "Unable to connect to database: $DB_NAME"

for required_table in groups group_permissions user_groups user_profiles; do
    TABLE_EXISTS="$(
        sudo -u postgres psql -d "$DB_NAME" -Atqc \
            "SELECT to_regclass('public.${required_table}') IS NOT NULL;"
    )"
    [[ "$TABLE_EXISTS" == "t" ]] \
        || fail "Required database table is missing: $required_table"
done

DUPLICATE_USERNAME_COUNT="$(
    sudo -u postgres psql -d "$DB_NAME" -Atqc "
        SELECT COUNT(*)
        FROM (
            SELECT LOWER(username)
            FROM user_profiles
            GROUP BY LOWER(username)
            HAVING COUNT(*) > 1
        ) duplicates;
    "
)"

[[ "$DUPLICATE_USERNAME_COUNT" =~ ^[0-9]+$ ]] \
    || fail "Unable to validate duplicate user profiles"
if [[ "$DUPLICATE_USERNAME_COUNT" -gt 0 ]]; then
    warn "$DUPLICATE_USERNAME_COUNT case-insensitive duplicate profile name(s) will be merged"
fi

ok "Database preflight passed"

###############################################################################
# Cleanup and rollback
###############################################################################

STAGE_DIR=""
BACKUP_DIR=""
RUNTIME_INSTALL_STARTED=0
RUNTIME_INSTALL_COMPLETE=0

on_exit() {
    local rc=$?
    trap - EXIT
    set +e

    if [[ "$rc" -ne 0 && "$RUNTIME_INSTALL_STARTED" -eq 1 \
        && -n "$BACKUP_DIR" && -d "$BACKUP_DIR" ]]; then
        warn "Update 003 failed after runtime installation started"
        warn "Restoring runtime files from backup"

        while IFS= read -r relative_path; do
            [[ -n "$relative_path" ]] || continue
            target_path="/$relative_path"
            backup_path="$BACKUP_DIR/runtime/$relative_path"

            if [[ -f "$backup_path" ]]; then
                mkdir -p "$(dirname "$target_path")"
                cp -a "$backup_path" "$target_path"
            else
                rm -f "$target_path"
            fi
        done < "$BACKUP_DIR/payload-files.txt"

        systemctl restart portal-api.service >/dev/null 2>&1 || true
        warn "Runtime files restored from: $BACKUP_DIR"
        warn "Additive database changes may remain and are safe to re-run"
    fi

    if [[ -n "$STAGE_DIR" && -d "$STAGE_DIR" ]]; then
        rm -rf "$STAGE_DIR"
    fi

    exit "$rc"
}

trap on_exit EXIT

###############################################################################
# Decode, extract and validate payload
###############################################################################

log "STAGING UPDATE 003 RUNTIME FILES"

STAGE_DIR="$(mktemp -d /tmp/portal-update-003.XXXXXX)"
chmod 700 "$STAGE_DIR"

PAYLOAD_B64="$STAGE_DIR/update003-payload.tar.gz.b64"
PAYLOAD_TGZ="$STAGE_DIR/update003-payload.tar.gz"
PAYLOAD_DIR="$STAGE_DIR/payload"
HASH_FILE="$STAGE_DIR/update003-files.sha256"

mkdir -p "$PAYLOAD_DIR"

