###############################################################################
# Backup current database and runtime files
###############################################################################

log "BACKING UP CURRENT PORTAL RUNTIME AND DATABASE"

BACKUP_DIR="/var/backups/portal/update-003-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$BACKUP_DIR/runtime"
chmod 700 "$BACKUP_DIR"

cp -a "$STAGE_DIR/payload-files.txt" "$BACKUP_DIR/payload-files.txt"

while IFS= read -r relative_path; do
    [[ -n "$relative_path" ]] || continue
    source_path="/$relative_path"

    if [[ -f "$source_path" ]]; then
        backup_path="$BACKUP_DIR/runtime/$relative_path"
        mkdir -p "$(dirname "$backup_path")"
        cp -a "$source_path" "$backup_path"
    fi
done < "$STAGE_DIR/payload-files.txt"

sudo -u postgres pg_dump --format=custom "$DB_NAME" \
    > "$BACKUP_DIR/dnsapproval-before-update003.dump"
chmod 600 "$BACKUP_DIR/dnsapproval-before-update003.dump"

pg_restore --list "$BACKUP_DIR/dnsapproval-before-update003.dump" >/dev/null \
    || fail "Database backup validation failed"

sha256sum \
    "$BACKUP_DIR/dnsapproval-before-update003.dump" \
    > "$BACKUP_DIR/SHA256SUMS"

ok "Backup created and validated: $BACKUP_DIR"

###############################################################################
# Additive, idempotent database migration
###############################################################################

log "APPLYING DATABASE CHANGES"

sudo -u postgres psql -v ON_ERROR_STOP=1 -d "$DB_NAME" <<'SQL'
BEGIN;

-- Update 003 makes usernames case-insensitive. Historical profiles that
-- differ only by capitalization represent the same account. Prefer the
-- spelling already used by user_groups, then the profile with a group, then
-- the oldest profile ID. Fill blank fields from the redundant variants before
-- removing them.
CREATE TEMP TABLE update003_profile_keepers ON COMMIT DROP AS
SELECT
    ranked.normalized_username,
    ranked.id AS keep_id
FROM (
    SELECT
        up.id,
        LOWER(up.username) AS normalized_username,
        ROW_NUMBER() OVER (
            PARTITION BY LOWER(up.username)
            ORDER BY
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM user_groups ug
                        WHERE ug.username = up.username
                    ) THEN 0
                    ELSE 1
                END,
                CASE WHEN up.group_id IS NOT NULL THEN 0 ELSE 1 END,
                up.id
        ) AS profile_rank
    FROM user_profiles up
) ranked
WHERE ranked.profile_rank = 1;

UPDATE user_profiles keep
SET
    display_name = COALESCE(
        NULLIF(BTRIM(keep.display_name), ''),
        (
            SELECT NULLIF(BTRIM(candidate.display_name), '')
            FROM user_profiles candidate
            WHERE LOWER(candidate.username) = LOWER(keep.username)
              AND candidate.id <> keep.id
              AND NULLIF(BTRIM(candidate.display_name), '') IS NOT NULL
            ORDER BY candidate.id
            LIMIT 1
        ),
        keep.display_name
    ),
    surname = COALESCE(
        NULLIF(BTRIM(keep.surname), ''),
        (
            SELECT NULLIF(BTRIM(candidate.surname), '')
            FROM user_profiles candidate
            WHERE LOWER(candidate.username) = LOWER(keep.username)
              AND candidate.id <> keep.id
              AND NULLIF(BTRIM(candidate.surname), '') IS NOT NULL
            ORDER BY candidate.id
            LIMIT 1
        )
    ),
    department = COALESCE(
        NULLIF(BTRIM(keep.department), ''),
        (
            SELECT NULLIF(BTRIM(candidate.department), '')
            FROM user_profiles candidate
            WHERE LOWER(candidate.username) = LOWER(keep.username)
              AND candidate.id <> keep.id
              AND NULLIF(BTRIM(candidate.department), '') IS NOT NULL
            ORDER BY candidate.id
            LIMIT 1
        )
    ),
    email_address = COALESCE(
        NULLIF(BTRIM(keep.email_address), ''),
        (
            SELECT NULLIF(BTRIM(candidate.email_address), '')
            FROM user_profiles candidate
            WHERE LOWER(candidate.username) = LOWER(keep.username)
              AND candidate.id <> keep.id
              AND NULLIF(BTRIM(candidate.email_address), '') IS NOT NULL
            ORDER BY candidate.id
            LIMIT 1
        )
    ),
    country_code = COALESCE(
        NULLIF(BTRIM(keep.country_code), ''),
        (
            SELECT NULLIF(BTRIM(candidate.country_code), '')
            FROM user_profiles candidate
            WHERE LOWER(candidate.username) = LOWER(keep.username)
              AND candidate.id <> keep.id
              AND NULLIF(BTRIM(candidate.country_code), '') IS NOT NULL
            ORDER BY candidate.id
            LIMIT 1
        )
    ),
    mobile_number = COALESCE(
        NULLIF(BTRIM(keep.mobile_number), ''),
        (
            SELECT NULLIF(BTRIM(candidate.mobile_number), '')
            FROM user_profiles candidate
            WHERE LOWER(candidate.username) = LOWER(keep.username)
              AND candidate.id <> keep.id
              AND NULLIF(BTRIM(candidate.mobile_number), '') IS NOT NULL
            ORDER BY candidate.id
            LIMIT 1
        )
    ),
    photo = COALESCE(
        NULLIF(BTRIM(keep.photo), ''),
        (
            SELECT NULLIF(BTRIM(candidate.photo), '')
            FROM user_profiles candidate
            WHERE LOWER(candidate.username) = LOWER(keep.username)
              AND candidate.id <> keep.id
              AND NULLIF(BTRIM(candidate.photo), '') IS NOT NULL
            ORDER BY candidate.id
            LIMIT 1
        )
    ),
    group_id = COALESCE(
        keep.group_id,
        (
            SELECT candidate.group_id
            FROM user_profiles candidate
            WHERE LOWER(candidate.username) = LOWER(keep.username)
              AND candidate.id <> keep.id
              AND candidate.group_id IS NOT NULL
            ORDER BY candidate.id
            LIMIT 1
        )
    )
FROM update003_profile_keepers keeper
WHERE keep.id = keeper.keep_id
  AND EXISTS (
      SELECT 1
      FROM user_profiles duplicate
      WHERE LOWER(duplicate.username) = keeper.normalized_username
        AND duplicate.id <> keeper.keep_id
  );

DELETE FROM user_profiles duplicate
USING update003_profile_keepers keeper
WHERE LOWER(duplicate.username) = keeper.normalized_username
  AND duplicate.id <> keeper.keep_id;

CREATE TABLE IF NOT EXISTS portal_settings (
    setting_key VARCHAR(100) PRIMARY KEY,
    setting_value TEXT NOT NULL,
    updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS user_custom_field_sections (
    id SERIAL PRIMARY KEY,
    section_name VARCHAR(100) NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS user_custom_fields (
    id SERIAL PRIMARY KEY,
    field_name VARCHAR(100) NOT NULL,
    field_key VARCHAR(100) NOT NULL,
    field_type VARCHAR(30) NOT NULL DEFAULT 'text',
    required BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    section_id INTEGER NOT NULL,
    prepend VARCHAR(50),
    append VARCHAR(50)
);

CREATE TABLE IF NOT EXISTS user_custom_field_values (
    user_id INTEGER NOT NULL,
    field_id INTEGER NOT NULL,
    field_value TEXT,
    updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, field_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS user_profiles_username_lower_unique
    ON user_profiles (LOWER(username));

CREATE UNIQUE INDEX IF NOT EXISTS user_custom_field_sections_name_lower_unique
    ON user_custom_field_sections (LOWER(section_name));

CREATE UNIQUE INDEX IF NOT EXISTS user_custom_fields_field_key_lower_unique
    ON user_custom_fields (LOWER(field_key));

CREATE INDEX IF NOT EXISTS user_custom_fields_section_id_idx
    ON user_custom_fields (section_id);

DO $migration$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'user_custom_fields_section_fk'
          AND conrelid = 'user_custom_fields'::regclass
    ) THEN
        ALTER TABLE user_custom_fields
            ADD CONSTRAINT user_custom_fields_section_fk
            FOREIGN KEY (section_id)
            REFERENCES user_custom_field_sections(id)
            ON DELETE RESTRICT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'user_custom_field_values_user_fk'
          AND conrelid = 'user_custom_field_values'::regclass
    ) THEN
        ALTER TABLE user_custom_field_values
            ADD CONSTRAINT user_custom_field_values_user_fk
            FOREIGN KEY (user_id)
            REFERENCES user_profiles(id)
            ON DELETE CASCADE;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'user_custom_field_values_field_fk'
          AND conrelid = 'user_custom_field_values'::regclass
    ) THEN
        ALTER TABLE user_custom_field_values
            ADD CONSTRAINT user_custom_field_values_field_fk
            FOREIGN KEY (field_id)
            REFERENCES user_custom_fields(id)
            ON DELETE CASCADE;
    END IF;
END
$migration$;

GRANT SELECT, INSERT, UPDATE, DELETE
    ON portal_settings,
       user_custom_field_sections,
       user_custom_fields,
       user_custom_field_values
    TO dnsapp;

GRANT USAGE, SELECT, UPDATE
    ON SEQUENCE user_custom_field_sections_id_seq,
                user_custom_fields_id_seq
    TO dnsapp;

COMMIT;
SQL

ok "Database migration completed"

###############################################################################
# Install staged runtime files
###############################################################################

log "INSTALLING UPDATE 003 RUNTIME FILES"

RUNTIME_INSTALL_STARTED=1

tar -xzf "$PAYLOAD_TGZ" -C /

if id www-data >/dev/null 2>&1; then
    install -d -o www-data -g www-data -m 775 \
        /opt/portal/web/uploads \
        /opt/portal/web/uploads/profiles \
        /opt/portal/web/uploads/appearance
else
    warn "www-data user not found; existing upload permissions were preserved"
fi

while IFS= read -r installed_php; do
    php -l "$installed_php" >/dev/null \
        || fail "Installed PHP validation failed: $installed_php"
done < <(find /opt/portal -type f -name '*.php' \
    | while IFS= read -r candidate; do
        relative_candidate="${candidate#/}"
        grep -Fxq "$relative_candidate" "$STAGE_DIR/payload-files.txt" \
            && printf '%s\n' "$candidate"
      done)

python3 -m py_compile /opt/portal/api/main.py \
    || fail "Installed Python validation failed: main.py"

(
    cd /
    sha256sum -c "$HASH_FILE" >/dev/null
) || fail "Installed Update 003 file checksum verification failed"

systemctl restart portal-api.service
systemctl is-active --quiet portal-api.service \
    || fail "portal-api.service failed after Update 003"

HTTP_STATUS="$(
    curl -sS -o "$STAGE_DIR/stats-response.json" -w '%{http_code}' \
        http://127.0.0.1:8000/stats || true
)"
[[ "$HTTP_STATUS" == "200" ]] \
    || fail "Portal API /stats health check failed with HTTP $HTTP_STATUS"

RUNTIME_INSTALL_COMPLETE=1

ok "Update 003 runtime files installed"
ok "portal-api.service restarted successfully"

###############################################################################
# Final verification
###############################################################################

log "VERIFYING UPDATE 003"

EXPECTED_TABLE_COUNT="$(
    sudo -u postgres psql -d "$DB_NAME" -Atqc "
        SELECT COUNT(*)
        FROM (VALUES
            ('portal_settings'),
            ('user_custom_field_sections'),
            ('user_custom_fields'),
            ('user_custom_field_values')
        ) AS required(table_name)
        WHERE to_regclass('public.' || table_name) IS NOT NULL;
    "
)"

[[ "$EXPECTED_TABLE_COUNT" == "4" ]] \
    || fail "Update 003 database table verification failed"

DNSAPP_TABLE_PRIVILEGES="$(
    sudo -u postgres psql -d "$DB_NAME" -Atqc "
        SELECT COUNT(*)
        FROM (VALUES
            ('portal_settings'),
            ('user_custom_field_sections'),
            ('user_custom_fields'),
            ('user_custom_field_values')
        ) AS required(table_name)
        WHERE has_table_privilege(
            'dnsapp',
            'public.' || table_name,
            'SELECT,INSERT,UPDATE,DELETE'
        );
    "
)"

[[ "$DNSAPP_TABLE_PRIVILEGES" == "4" ]] \
    || fail "dnsapp table privilege verification failed"

ok "Database verification completed"
ok "All 34 runtime checksums verified"
ok "API health check returned HTTP 200"

log "UPDATE 003 COMPLETE"
ok "Update 003 installed successfully"
